INSERT INTO `ExampleSentence` VALUES (6939,3213,'明日の試験はとても難しいですから、頑張ってください。','Ashita no shiken wa totemo muzukashii desu kara, ganbatte kudasai.','Karena ujian besok sangat sulit, berjuanglah.',1),(6940,3213,'日本の大学の入学試験のために、毎日5時間勉強しています。','Nihon no daigaku no nyuugaku shiken no tame ni, mainichi gojikan benkyou shiteimasu.','Demi ujian masuk universitas Jepang, saya belajar 5 jam setiap hari.',1),(6941,3213,'卒業するために、来月面接試験を受けます。','Sotsugyou suru tame ni, raigetsu mensetsu shiken wo ukemasu.','Untuk lulus, saya akan mengikuti ujian wawancara bulan depan.',1),(6942,3213,'日本へ留学したことは、私にとって良い経験になりました。','Nihon he ryuugaku shita koto wa, watashi ni totte yoi keiken ni narimashita.','Belajar di Jepang telah menjadi pengalaman yang baik bagi saya.',1),(6943,3213,'化学の授業で, 水の性質を調べる実験を行いました。','Kagaku no jugyou de, mizu no seishitsu wo shiraberu jikken wo okonaimashita.','Dalam kelas kimia, kami melakukan eksperimen untuk memeriksa sifat-sifat air.',1),(6944,3214,'この問題は少し難しいです。','Kono mondai wa sukoshi muzukashii desu.','Soal ini sedikit sulit.',1),(6945,3214,'先生に質問してください。','Sensei ni shitsumon shitekudasai.','Silakan bertanya kepada guru.',1),(6946,3214,'日本では環境問題が重要です。','Nihon dewa kankyou mondai ga juuyou desu.','Di Jepang, masalah lingkungan adalah hal yang penting.',1),(6947,3214,'この問題集で勉強します。','Kono mondaishuu de benkyou shimasu.','Saya belajar menggunakan buku kumpulan soal ini.',1),(6948,3214,'電話で問い合わせをしました。','Denwa de toiawase wo shimashita.','Saya mengajukan pertanyaan via telepon.',1),(6949,3215,'宿題が多すぎて、昨日は寝る時間がありませんでした。','Shukudai ga oosugite, kinou wa neru jikan ga arimasen deshita.','Karena PR terlalu banyak, kemarin saya tidak punya waktu tidur.',1),(6950,3215,'今日のゼミでは、卒業論文の論題について議論します。','Kyou no zemi dewa, sotsugyou ronbun no rondai ni tsuite giron shimasu.','Di seminar hari ini, kami akan mendiskusikan tema tesis kelulusan.',1),(6951,3215,'面接試験では、最近の時事問題について質問されました。','Mensetsu shiken dewa, saikin no jiji mondai ni tsuite shitsumon saremashita.','Dalam ujian wawancara, saya ditanya tentang isu-isu aktual baru-baru ini.',1),(6952,3215,'彼女は自分の留学経験を題材にして小説を書きました。','Kanojo wa jibun no ryuugaku keiken wo daizai ni shite shousetsu wo kakimashita.','Dia menulis novel berdasarkan pengalaman belajarnya di luar negeri.',1),(6953,3215,'今週は課題がたくさんありますから、とても忙しいです。','Konshuu wa kadai ga takusan arimasu kara, totemo isogashii desu.','Karena minggu ini ada banyak tugas, saya sangat sibuk.',1),(6954,3216,'先生の質問に答えました。','Sensei no shitsumon ni kotaemashita.','Saya menjawab pertanyaan guru.',1),(6955,3216,'正しい答えを書いてください。','Tadashii kotae wo kaite kudasai.','Silakan tulis jawaban yang benar.',1),(6956,3216,'回答をメールで送りました。','Kaitou wo meeru de okurimashita.','Saya mengirimkan jawaban melalui email.',1),(6957,3216,'応答はなかなかありません。','Outou wa naka naka arimasen.','Responnya tidak kunjung datang.',1),(6958,3216,'一問一答はどういう意味ですか。','Ichimon ittou wa dou iu imi desu ka.','Apa arti dari \'satu pertanyaan satu jawaban\'?',1),(6959,3217,'先生はテストを採点しました。','Sensei wa tesuto wo saiten shimashita.','Guru menilai ujian tersebut.',1),(6960,3217,'私は百点を取りました。','Watashi wa hyakuten wo torimashita.','Saya mendapatkan nilai 100.',1),(6961,3217,'この作文の要点を書いてください。','Kono sakubun no youten wo kaite kudasai.','Silakan tulis poin penting dari esai ini.',1),(6962,3217,'先生は問題点を説明しました。','Sensei wa mondaiten wo setsumei shimashita.','Guru menjelaskan titik permasalahannya.',1),(6963,3217,'出発地点は駅です。','Shuppatsu chiten wa eki desu.','Titik keberangkatannya adalah stasiun.',1),(6966,3219,'研究の意味を調べます。','研究 no imi wo shirabemasu.','Memeriksa arti dari 研究 (Penelitian).',1),(6967,3219,'探究について勉強します。','探究 ni tsuite benkyou shimasu.','Belajar tentang 探究 (Pencarian).',1),(6968,3220,'集会の意味を調べます。','集会 no imi wo shirabemasu.','Memeriksa arti dari 集会 (Pertemuan).',1),(6969,3220,'集合について勉強します。','集合 ni tsuite benkyou shimasu.','Belajar tentang 集合 (Berkumpul).',1),(6970,3221,'調査の意味を調べます。','調査 no imi wo shirabemasu.','Memeriksa arti dari 調査 (Investigasi).',1),(6971,3221,'調整について勉強します。','調整 ni tsuite