--
-- Table structure for table `Kanji`
--

DROP TABLE IF EXISTS `Kanji`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `Kanji` (
  `id` int NOT NULL AUTO_INCREMENT,
  `character` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `romaji` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `meaning` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `moduleId` int DEFAULT NULL,
  `baseMeaning` text COLLATE utf8mb4_unicode_ci,
  `bushuu` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `kunyomi` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `onyomi` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `isJukugo` tinyint(1) NOT NULL DEFAULT '0',
  `border` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `Kanji_character_key` (`character`),
  KEY `Kanji_moduleId_fkey` (`moduleId`),
  CONSTRAINT `Kanji_moduleId_fkey` FOREIGN KEY (`moduleId`) REFERENCES `Module` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=3488 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

