--
-- Table structure for table `Quiz`
--

DROP TABLE IF EXISTS `Quiz`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `Quiz` (
  `id` int NOT NULL AUTO_INCREMENT,
  `kanjiId` int NOT NULL,
  `question` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `correctAnswer` text COLLATE utf8mb4_unicode_ci,
  `explanation` text COLLATE utf8mb4_unicode_ci,
  `correctOrder` text COLLATE utf8mb4_unicode_ci,
  `groups` text COLLATE utf8mb4_unicode_ci,
  `leftItems` text COLLATE utf8mb4_unicode_ci,
  `options` text COLLATE utf8mb4_unicode_ci,
  `pairs` text COLLATE utf8mb4_unicode_ci,
  `rightItems` text COLLATE utf8mb4_unicode_ci,
  `targetWord` text COLLATE utf8mb4_unicode_ci,
  `type` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'multiple',
  `words` text COLLATE utf8mb4_unicode_ci,
  PRIMARY KEY (`id`),
  KEY `Quiz_kanjiId_fkey` (`kanjiId`),
  CONSTRAINT `Quiz_kanjiId_fkey` FOREIGN KEY (`kanjiId`) REFERENCES `Kanji` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=4869 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

