  `masterRefleksiId` int DEFAULT NULL,
  `question` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `answer` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `createdAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updatedAt` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `RefleksiData_userId_fkey` (`userId`),
  KEY `RefleksiData_kanjiId_fkey` (`kanjiId`),
  KEY `RefleksiData_masterRefleksiId_fkey` (`masterRefleksiId`),
  CONSTRAINT `RefleksiData_kanjiId_fkey` FOREIGN KEY (`kanjiId`) REFERENCES `Kanji` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `RefleksiData_masterRefleksiId_fkey` FOREIGN KEY (`masterRefleksiId`) REFERENCES `MasterRefleksi` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `RefleksiData_userId_fkey` FOREIGN KEY (`userId`) REFERENCES `User` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
