INSERT INTO `SemanticRelation` VALUES (12177,3213,'Ujian','Hubungan makna antar kanji  試 dan 験,  menunjukan bahwa gabungan kedua kanji itu  mengandung makna \"menguji kemampuan untuk membuktikan penguasan seseorang\".','試','Menguji','験','Membuktikan hasil','試験'),(12178,3213,'Mengikuti ujian','Hubungan makna antar kanji 受 dan 験, menunjukan bahwa gabungan kedua kanji itu  mengandung makna \"seseorang mengikuti proses ujian\".','受','Menerima','験','Ujian/verifikasi','受験'),(12179,3213,'ujian sertifikasi','Hubungan makna dari kanji 資格, menunjukan bahwa gabungan kedua kanji itu  mengandung makna \"ujian fungsinya untuk membuktikan kompetesnsi tertentu.\"','資','kualifikasi','格','ujian','資格試験'),(12180,3213,'pengalaman','Hubungan makna antar kanji 経 dan 験, menunjukan bahwa gabungan kedua kanji itu  mengandung makna\" sesuatu yang telah dialami secara langsung\".','経','Melewati','験','Mengalami','経験'),(12181,3213,'pengalaman langsung','Hubungan makna antar 体 dan 験 , menunjukan bahwa gabungan kedua kanji itu  mengandung makna \"pengalaman yang dirasakan sendiri secara nyata\".','体','badan','験','mengalami','体験'),(12182,3213,'orang yang berepangalam','Hubungan makna antar kanji体 dan 験, menunjukan bahwa gabungan kedua kanji itu  mengandung makna \" orang yang telah memiliki pengalaman.\"','経','Pengalaman','験','Orang','経験者'),(12183,3213,'eksperimen','Hubungan makna dari kanji 実　dan 験, menunjukan bahwa gabungan kedua kanji itu  mengandung makna \"pembuktian suatu teori melalui percobaan\".','実','nyata','験','pembuktian','実験'),(12184,3213,'laboratorium','Hubungan makna antar kanji 実験 dan 室, menunjukan bahwa gabungan kedua kanji itu  mengandung makna \"tempat melakukan eksperimen\"','実','percobaan','験','ruangan','実験室'),(12185,3213,'subjek penelitian','Hubungan makna antar kanji dari 被, 験 dan 者, menunjukan bahwa gabungan ketiga kanji itu  mengandung makna \"orang yang menjadi objek eksperimen atau penelitian\".','被','yang dikenai','験','menguji','被験者'),(12186,3213,'peserta ujian','Hubungan makna antar kanji 受験 dan 生, menunjukan bahwa gabungan kedua kanji itu  mengandung makna \"seseorang sedang mengikuti ujian\".','受','mengikuti ujian','験','siswa/pelajar','受験生'),(12187,3213,'ujian sertifikasi','Hubungan makna dari kanji検 dan 定, menunjukan bahwa gabungan kedua kanji itu  mengandung makna\" proses pemeriksaan untuk menetapkan kemampuan seseorang\".','検','memeriksa','定','menetapkan standar','検定試験'),(12188,3213,'ujian','Hubungan makna dari kanji試 dan験, menunjukan bahwa gabungan kedua kanji itu  mengandung makna \"menguji kemampuan seseorang\".','試','menguji','験','ujian','試験'),(12189,3213,'nomor peserta ujian','Hubungan makna antar kanji 受験 dan 番号 saat disatukan menjadi 受験番号, menunjukan bahwa gabungan kedua kosakata kanji tersebut,  mengandung makna \"nomor identitas khusus yang diberikan kepada peserta ujian untuk memastikan pengenalan dan verifikasi data diri selama seluruh rangkain ujian berlangsung\".','受','mengikuti ujian','験','nomor identitas','受験番号'),(12190,3214,'soal/masalah','Hubungan makna antar kanji 問 dan 題 menjadi 問題,  menunjukan bahwa gabungan kedua kanji itu  mengandung makna \"sebagai persoalan yang harus diselesaikan\".','問','bertanya','題','persoalan','問題'),(12191,3214,'pertanyaan','Hubungan makna antar kanji  質dan 問 menjadi 質問, menunjukan bahwa gabungan kedua kanji itu  mengandung \"pertanyaan yang dikemukakan agar memperoleh suatu informasi\",','質','kualitas/inti','問','bertanya','質問'),(12192,3214,'tanya jawab','Hubungan makna antar kanji  問dan 答 ketika digabungkan menjadi 問答, menunjukan bahwa gabungan kedua kanji itu  mengandung makna　\" suatu kegiatan saling bertanya jawab antara pembicara dan lawan bicara\".','問','bertanya','答','menjawab','問答'),(12193,3214,'wawasan medis','Hubungan makna antar kanji 問 dan 診 ketika digabung menjadi 問診,  menunjukan bahwa gabungan kanji tersebut  mengandung makna \"pemerikasaan pasein melalaui serangkaian pertanyaan\".','問','bertanya','診','memeriksa','問診'),(12194,3214,'introgasi','Hubungan makna antar kanji 尋 dan問 ketika digabung menjadi 尋問, menunjukan bahwa gabungan  kanji tersebut   mengandung makna \"proses pengajuan pertanyaan secara mendalam untuk memperoleh suatu keterangan informasi\".','尋','menyelidiki','問','bertanya','尋問'),(12195,3214,'survei lapangan','Hubungan makna antar kanji 訪問 dan 調査, ketika digabung menjadi dua kosakata yaitu 訪問調査, menunjukan bahwa gabungan kedua kosakata kanji tersebut   mengandung makna \"pengumpulan data yang dilakukan melalui kunjungan langsung\".','訪','mengunjungi','問','penyelidikan','訪問調査'),(12196,3214,'titik masalah','Hubungan makna antar kanji 問題 dan点, ketika digabungkan menjadi 問題点, menunjukan bahwa gabungan  kedua kanji tersebut   mengandung makna \"bagian yang menjadi fokus masalah.\"','問','masalah','題','titik atau poin','問題点'),(12197,3214,'masalah sosial','Hubungan makna antar kanji 社会 dan 問題, ketika digabungkan menjadi 社会問題, menunjukan bahwa gabungan dua kosakata kanji tersebut, mengandung makna \"masalah yang dihadapi dalam kehidupan masyarat\".','社','masyarakat','会','masalah','社会問題'),(12198,3214,'masalah lingkungan','Hubungan makna antar kanji 環境 dan　問題 , ketika digabungkan menjadi 環境問題, menunjukan bahwa gabungan  kanji tersebut   mengandung makna \"suatu persoalan yang berhubungan dengan lingkungan hidup\".','環','lingkungan','境','masalah','環境問題'),(12199,3214,'butir pertanyaan','Hubungan makna antar kanji 設 dan 問, ketika digabungan menjadi 設問, menunjukan bahwa gabungan  kanji tersebut   mengandung makna　 \"pertanyaan yang disusun dalam test atau angket\".','設','menyusun','問','pertanyaan','設問'),(12200,3214,'kumpulan soal','Hubungan makna antar kanji 問題 dan集, ketika digabungkan menjadi 問題集,  menunjukan bahwa gabungan  kanji tersebut   mengandung makna \"buku yang berisi kumpulan berbagai latihan soal\".','問','soal','題','kumpulan','問題集'),(12201,3214,'soal nomor satu','Hubungan makna antar kanji 問 dan一, ketika digabung menjadi 問一、menunjukan bahwa gabungan  kanji tersebut   mengandung makna nomor \"pertama dalam suatu latihan atau ujian\".','問','soal','一','satu','問一'),(12202,3214,'pertanyaan/inquiry','Hubungan makna antar kanji 問 dan 合わせ, ketika digabungan menjadi 問い合わせ、menunjukan bahwa gabungan  kanji tersebut   mengandung makna \"menghubungi seseorang untuk memperoleh informasi\".','問','bertanya','い','menghubungkan','問い合わせ'),(12203,3215,'Soal/masalah','Hubungan makna antar kanji 問 dan 題 ketika digabungkan menjadi 問題、menunjukan bahwa gabungan  kanji tersebut   mengandung makna suatu persoalan atau \"masalah yang harus diselesaikan\".','問','bertanya','題','topik atau persoalan','問題'),(12204,3215,'Tugas','Hubungan makna antara kanji 課 dan 題、ketika digabung menjadi 課題, menunjukan bahwa gabungan  kanji tersebut   mengandung makna  \"tugas yang diberikan untuk dikerjakan\".','課','Pelajaran/mata kuliah','題','Topik','課題'),(12205,3215,'pekerjaan rumah','Hubungan makna antar kanji 宿 dan 題 apabila digabungkan menjadi 宿題、 menunjukan bahwa gabungan  kanji tersebut   mengandung makna \"sesuatu tugas yang dikerjakan di rumah\".','宿','tempat tinggal/rumah','題','tugas','宿題'),(12206,3215,'judul','Hubungan makna antar kanji 題dan 名, ketika digabungkan menjadi 題名、menunjukan bahwa gabungan  kanji tersebut   mengandung makna menunjukan makna atau arti nama sebuah tulisan atau karya.','題','judul','名','nama','題名'),(12207,3215,'judul utama','Hubungan makna antar kanji 表 dan題, ketika digabungkan menjadi 表題、menunjukan bahwa gabungan  kanji tersebut   mengandung makna \"judul yang muncul pada bagian dokumen\".','表','bagian depan','題','judul','表題'),(12208,3215,'tema utama','Hubungan makna antar kanji 主 dan 題, ketika digabungkan menjadi kanji  主題、 menunjukan bahwa gabungan  kanji tersebut   mengandung makna  \"pokok pembahasan utama\".','主','utama','題','tema','主題'),(12209,3215,'topik penelitian','Hubungan makna antar kanji 研究 dan課題, ketika digabungkan menjadi  研究課題、 menunjukan bahwa gabungan  kanji tersebut   mengandung makna \"suatu masalah yang menjadi fokus penelitian\".','研','penelitian','究','tugas','研究課題'),(12210,3215,'tema kajian','Hubungan makna antar kanji 論dan題, ketika digabungkan menjadi kanji論題、menunjukan bahwa gabungan  kanji tersebut   mengandung makna \"topik yang dibahas secara akademik\".','論','argumen/diskusi','題','tema','論題'),(12211,3215,'pembuatan soal','Hubungan makna antar kanji 出dan題, ketika digabungkan menjadi kanji出題、menunjukan bahwa gabungan  kanji tersebut   mengandung makna \"kegiatan membuat atau mengeluarkan soal\".','出','mengeluarkan','題','soal','出題'),(12212,3215,'topik pembicaraan','Hubungan makna antar kanji 話 dan 題, menunjukan bahwa gabungan kedua kanji itu  mengandung makna\" sesuatu hal yang sedang dibicarakan\".','話','berbicara','題','topik','話題'),(12213,3215,'isu aktual','Hubungan makna antar kanji 時事 dan 問題 saat digabungkan 時事問題、menunjukan bahwa gabungan  kanji tersebut   mengandung makna \"persoalan yang sedang hangat dibicarakan di ｍasyarakat\".','時','peristiwa terkini','事','masalah','時事問題'),(12214,3215,'kesadaran masalah','Hubungan makna antar kanji 問題 dan 意識 saat digabungkan menjadi 問題意識、menunjukan bahwa gabungan  kanji tersebut   mengandung makna \"suatu kemampuan adanya persoalan yang perlu diselesaikan\".','問','masalah','題','kesadaran','問題意識'),(12215,3215,'bahan cerita','Hubungan makna antar kanji 題 dan材, saat digabungakan menjadi kanji 題材、menunjukan bahwa gabungan  kanji tersebut   mengandung makna\"bahan atau tema yang digunakan untuk membuat sebuah karya\" (kotobank digital jiten)','題','tema','材','bahan','題材'),(12216,3215,'tulisan judul','Hubungan makna antar kanji 題 dan字 ketika digabung menjadi 題字、menunjukan bahwa gabungan  kanji tersebut   mengandung makna \"tulisan yang digunakan sebagai judul\".','題','judul','字','huruf/lisan','題字'),(12217,3215,'judul presentasi','Hubungan makna antar kanji dari kanji 演 dan題, ketika digabung menjadi 演題、menunjukan bahwa gabungan  kanji meengandung makna \"judul sebuah presentasi, seminar, atau pidato.\"','演','presentasi / pertunjukan','題','judul','演題'),(12218,3216,'jawaban','Hubungan makna antar kanji 回 dan 答, menunjukan bahwa gabungan kedua kanji itu  mengandung makna \"jawaban yang diberikan terhadap suatu pertanyaan atau perminataan informasi\" (kanji pedia, 2026).','回','mengembalikan','答','jawaban','回答'),(12219,3216,'soal jawaban','Hubungan makna antar kanji 解 dan 答,  menunjukan bahwa gabungan kedua kanji itu  mengandung makna \"jawaban yang digunakan untuk menyelesaikan soal atau permasalahan\".','解','menyelesaikan','答','jawaban','解答'),(12220,3216,'respons','Hubungan makna antar kanji 応dan 答, menunjukan bahwa gabungan kedua kanji itu  mengandung makna\"respons yang diberikan terhadap pertanyaan, panggilan, atau komunikasi\".','応','menanggapi','答','jawaban','応答'),(12221,3216,'lembar jawaban','Hubungan makna antar kanji 答 dan 案, menunjukan bahwa gabungan kedua kanji itu  mengandung makna \"lembar jawaban untuk menuliskan jawaban dalam ujian atau latihan\"','答','jawaban','案','naskah','答案'),(12222,3216,'jawaban benar','Hubungan makna antar kanji 正 dan 答 menjadi 正答, menunjukan bahwa gabungan kedua kanji itu mengandung makna \"jawaban yang benar terhadap suatu pertanyaan atau soal\".','正','benar','答','jawaban','正答'),(12223,3216,'kertas jawaban','Hubungan makna antar kanji 解答 dan用紙 menjadi 解答用紙, menunjukan bahwa gabungan kedua kanji itu  mengandung makna \"sebuah lembaran resmi yang digunakan untuk menuliskan jawaban peserta ujian\".','解','jawaban','答','lembar kertas','解答用紙'),(12224,3216,'balasan','Hubungan makna antar kanji  返 dan 答 menjadi　返答, menunjukan bahwa gabungan kedua kanji itu  mengandung makna \"jawaban atau balasan terhadap pertanyaan, suray, maupun pesan\"','返','mengembalikan','答','jawaban','返答'),(12225,3216,'jawaban lisan','Hubungan makna antar kanji 口 dan 答 menjadi口答, menunjukan bahwa gabungan kedua kanji itu  mengandung makna \"jawaban yang disampaikan secara lisan\"','口','mulut','答','jawaban','口答'),(12226,3216,'penjelasan resmi','Hubungan makna antar kanji 答 dan 弁 menjadi　答弁, menunjukan bahwa gabungan kedua kanji itu  mengandung makna \" jawaban resmi yang diberikan dalam rapat,siding atau pun forum\".','答','menjawab','弁','penjelasan','答弁'),(12227,3216,'tanya jawab','Hubungan makna antar kanji 問 dan 答　menjadi問答, menunjukan bahwa gabungan kedua kanji itu  mengandung makna \"suatu kegiatan tanya jawab sebagai proses pembelajaran\".','問','bertanya','答','menjawab','問答'),(12228,3216,'satu pertanyaan satu jawaban','Hubungan makna antar kanji 一、問、一、dan答 menjadi 一問一答, menunjukan bahwa gabungan kedua kanji itu  mengandung makna \" metode belajar yang menyajikan satu pertanyaan untuk satu jawaban\".','一','satu pertanyaan','問','satu jawaban','一問一答'),(12229,3216,'rekomnedasi resmi','Hubungan makna antar kanji 答 dan 申 menjadi 答申, menunjukan bahwa gabungan kedua kanji itu  mengandung makna \"jawaban resmi yang disampaikan kepada pihak yang meminta pertimbangan\".','答','menjawab','申','menyampaikan','答申'),(12230,3216,'jawaban otomatis','Hubungan makna antar kanji 自動 dan 応答　menjadi 自動応答, menunjukan bahwa gabungan kedua kanji itu  mengandung makna \"jawaban yang diberikan secara otomatis oleh sistem komputer atau perangkat\"','自','otomatis','動','respons','自動応答'),(12231,3216,'waktu respons','Hubungan makna antar kanji  応答 dan 時間　menjadi応答時間, menunjukan bahwa gabungan kedua kanji itu  mengandung makna \" lamanya waktu yang diperlukan seseorang atau sistem untuk memberikan jawaban\".','応','respons','答','waktu','応答時間'),(12232,3216,'tingkat respons','Hubungan makna antar kanji  応答 dan 率　menjadi応答率, menunjukan bahwa gabungan kedua kanji itu  mengandung makna \"presentase jumalah respons yang diterima dibanding jumlah pertanyaan\".','応','respons','答','tingkat','応答率'),(12233,3217,'penilaian','Hubungan makna antar kanji 採 dan 点, saat digabungkan menjadi 採点, menunjukan bahwa gabungan kedua kanji itu  mengandung makna “ kegiatan memberikan nilai terhadap hasil pekerjaan”','採','memberi/mengambil','点','nilai','採点'),(12234,3217,'skor','Hubungan makna antar kanji 得 dan点 saat digabung menjadi 得点,  menunjukan bahwa gabungan kedua kanji itu  mengandung makna “jumlah nilai yang diperoleh seseorang”.','得','memperoleh','点','poin','得点'),(12235,3217,'pengurangan nilai','Hubungan makna antar kanji減 dan 点 , mumjukan gabungan kanji  ini saat digabung menjadi 減点,  menunjukan bahwa gabungan kedua kanji itu  mengandung makna \"nilai yang dikurangi \".','減','mengurangi','点','nilai','減点'),(12236,3217,'lokasi','Hubungan makna antar kanji　地dan 点、menjadi 地点 , menunjukan bahwa gabungan kedua kanji itu  mengandung makna \"titik tertentu pada suatu lokasi\"','地','tempat','点','titik','地点'),(12237,3217,'titik awal','Hubungan makna antar kanji 起 dan 点 , menunjukan  bahwa gabungan  dua kanji  terserbut mengandung makna \"tempat dimulainya suatu perjalanan atau aktivitas\" .','起','mulai','点','awal','起点'),(12238,3217,'titik akhir','Hubungan makna antar kanji 終 dan 点 , menunjukan  bahwa gabungan  dua kanji  terserbut  mengandung makna  “tempat berakhirnya suatu perjalanan”.','終','selesai','点','tempat','終点'),(12239,3217,'sudut pandang','Hubungan makna antar kanji 観 dan 点 menjadi 観点、menunjukan gabungaan dua kanji tersebut mengandung makna \"cara melihat/memandang  suatu persoalan \"','観','melihat','点','titik','観点'),(12240,3217,'persepketif','Hubungan makna antar kanji 視 dan 点 menjadi 視点, menunjukan bahwa gabungan dua kanji tersebut mengandung makna \"posisi atau sudut pandang dalam memahami suatu masalah\".','視','melihat','点','titik','視点'),(12241,3217,'pokok bahasan','Hubungan makna antar kanji 論 dan 点 menjadi 論点, menunjukan bahwa gabungan dua kanji tersebut mengandung makna \"masalah utama yang menjadi inti pembahasaan\".','論','pembahasan','点','pokok','論点'),(12242,3217,'titik masalah','Hubungan makna antar kanji 問題 dan 点 menjadi 問題点, menunjukan bahwa gabungan kedua  kanji tersebut mengandung makna \"bagian yang menjadi sumber masalah\".','問','masalah','題','titik','問題点'),(12243,3217,'fokus utama','Hubungan makna antar kanji 重  dan 点 menjadi 重点, menunjukan bahwa gabungan kedua  kanji tersebut mengandung makna \"bagian yang terpenting untuk diperhatikan\"','重','penting','点','titik','重点'),(12244,3217,'poin penting','Hubungan makna antar kanji 要  dan 点 menjadi 要点, menunjukan bahwa gabungan kedua  kanji tersebut mengandung makna \"poko dari suatu penjelasan\".','要','inti','点','poin','要点'),(12245,3217,'pemeriksaan','Hubungan makna antar kanji   点 dan 検 menjadi 点検, menunjukan bahwa gabungan kedua  kanji tersebut mengandung makna \"keadaan memeriksa kondisi suatu benda atau sistem\".','点','memeriksa','検','inspeksi','点検'),(12246,3217,'penerangan','Hubungan makna antar kanji点 dan 灯 menjadi 点灯、, menunjukan bahwa gabungan kedua  kanji tersebut mengandung makna \"menghidupkan lampu aatau penerangan\".','点','menyalakan','灯','lampu','点灯'),(12612,3284,'kegiatan memberikan nilai terhadap hasil pekerjaan','Hubungan makna antar kanji 採 dan 点, saat digabungkan menjadi 採点, menunjukan bahwa gabungan kedua kanji itu mengandung makna \'kegiatan memberikan nilai terhadap hasil pekerjaan\'','採','memberi / mengambil','点','nilai','採点'),(12613,3285,'jumlah nilai yang diperoleh seseorang','Hubungan makna antar kanji 得 dan 点 saat digabung menjadi 得点, menunjukan bahwa gabungan kedua kanji itu mengandung makna \'jumlah nilai yang diperoleh seseorang\'','得','memperoleh','点','poin','得点'),(12614,3286,'nilai yang dikurangi','Hubungan makna antar kanji 減 dan 点, menunjukan bahwa gabungan kedua kanji itu mengandung makna \'nilai yang dikurangi\'','減','mengurangi','点','nilai','減点'),(12615,3287,'titik tertentu pada suatu lokasi','Hubungan makna antar kanji 地 dan 点 menjadi 地点, menunjukan bahwa gabungan kedua kanji itu mengandung makna \'titik tertentu pada suatu lokasi\'','地','tempat','点','titik','地点'),(12616,3288,'tempat dimulainya suatu perjalanan atau aktivitas','Hubungan makna antar kanji 起 dan 点, menunjukan bahwa gabungan dua kanji tersebut mengandung makna \'tempat dimulainya suatu perjalanan atau aktivitas\'','起','mulai','点','awal','起点'),(12617,3289,'tempat berakhirnya suatu perjalanan','Hubungan makna antar kanji 終 d